T("A Suite look, font, minimum height and position for Blizzard dialogs, marked resurrection offers, the item quality written on loot toasts and gold-framed money toasts.", "为暴雪对话框提供Suite外观、字体、最小高度和位置，标记复活请求，在拾取提示上写出物品品质，并为金钱提示加上金色边框。")
