T("A cinematic Suite screen with your character while you are AFK. Move or use /afk to return.", "暂离时显示带有你角色的 Suite 电影式画面。移动或输入 /afk 即可返回。")
T("A class in your group can provide this buff.", "队伍中的某个职业可以提供此增益。")
T("A clean minimap in its own frame: size, shape, border, zoom, Blizzard buttons, an addon button drawer and information texts. Blizzard's minimap buttons keep working.", "独立框体中的简洁小地图：大小、形状、边框、缩放、暴雪按钮、插件按钮收纳栏和信息文字。暴雪的小地图按钮仍可正常使用。")
T("A click-through surface follows each Blizzard chat window. Blizzard and MSUF Edit Mode keep their normal move and resize controls.", "每个暴雪聊天窗口都附有一层点击穿透的背景面板。暴雪和 MSUF 编辑模式仍保留正常的移动和调整大小控制。")
T("A colored plate sits behind the map and its border. Padding extends it beyond the map edge.", "地图及其边框后方有一块彩色底板。内边距会让它延伸到地图边缘之外。")
T("A compact clock, FPS and latency bar.", "紧凑显示时间、帧率和延迟。")
T("A compact, movable history of your recent successful spells.", "一份关于你最近成功法术的紧凑、可移动的历史记录。")
T("A frame-rate readout can sit below the strip or on its own, placed in MSUF Edit Mode. The MSUF Suite FPS key binding shows or hides it for this session, in combat too; a new choice here replaces that session switch.", "帧数显示可以放在属性条下方或单独放置，在 MSUF 编辑模式中摆放。MSUF Suite 的 FPS 按键可在本次会话中显示或隐藏它，战斗中也可用；在这里做出新选择会取代该会话开关。")
T("A movable strip for critical strike, haste, mastery and versatility.", "显示暴击、急速、精通和全能的可移动紧凑信息条。")
T("A movable summary after a Mythic+ run or raid boss kill.", "在史诗钥石挑战或团队首领击杀后显示可移动的总结。")
T("A ring around the mouse pointer that is easy to spot, optionally filled by your global cooldown or cast.", "鼠标指针周围醒目的圆环，可选用公共冷却或施法进度填充。")
T("A ring around the mouse pointer that makes it easy to find. Pick its shape, size, color, an optional short trail and a centre dot; No ring keeps only the dot or the progress fill. The camera mode shows ring, dot and trail only while you hold a mouse button down on the game world to turn the camera. The highlight follows the pointer only while something is shown, and it moves nothing while the pointer rests.", "在鼠标指针周围显示圆环，方便找到指针。可选择形状、大小、颜色、短拖尾和中心圆点；“无圆环”只保留圆点或进度填充。镜头模式仅在你于游戏世界中按住鼠标键转动镜头时显示圆环、圆点和拖尾。高亮只在有内容显示时跟随指针，指针静止时不会移动任何东西。")
T("A small summary sits beside the Character tab of your character sheet and leaves with it. It lists your gear with gem sockets and how many are filled, open ones in amber (click a line to open socketing), the total durability of your gear and, if you like, your PvP item level. Its buttons open the Great Vault and the current expansion page. It updates while the sheet is open, at most once per frame.", "一个小摘要位于角色面板的角色标签旁，并随其一同隐藏。它列出带宝石插槽的装备及已镶嵌数量，空插槽以琥珀色显示（点击一行打开镶嵌），装备的总耐久度，以及可选的PvP物品等级。其按钮可打开宏伟宝库和当前资料片页面。面板打开时更新，每帧最多一次。")
T("A soft light behind the map, independent of the border and artwork.", "地图后方的柔和光晕，独立于边框和装饰图。")
T("A summary with gem sockets, durability, PvP item level and Great Vault and expansion buttons, durability on the model, cropped slot icons and item levels on equipment choices.", "包含宝石插槽、耐久度、PvP物品等级以及宏伟宝库和资料片按钮的摘要，模型上的耐久度，裁剪的装备栏图标，以及装备选择中的物品等级。")
