T("Adds automatic collection on top of Blizzard's own Auto Loot setting, which stays unchanged. Locked slots and confirmations stay manual.", "在暴雪自身的“自动拾取”设置之上增加自动拾取，原设置保持不变。锁定的栏位和需要确认的拾取仍需手动处理。")
T("Adds guild rank, the hovered unit's target, item levels, the unit's current mount and item or spell details to Blizzard's main tooltip, and can show player names without titles. Your own item level and the one of the unit open in the Inspect window need no request. Item levels of other hovered players are a separate choice that sends inspect requests: at most one per hover, never while the Inspect window or another inspect is busy. Mounts are read once when a unit tooltip opens, out of combat; a change appears on the next hover. Place the fixed corner in MSUF Edit Mode; the cursor offsets apply to the cursor anchor.", "为暴雪主鼠标提示添加公会会阶、单位的目标、物品等级、单位当前的坐骑以及物品或法术详情，并可显示不带头衔的玩家名称。你自己的物品等级和观察窗口中已打开单位的物品等级无需请求。鼠标所指其他玩家的物品等级是单独的选项，会发送观察请求：每次悬停最多一次，观察窗口或其他观察正在进行时绝不发送。坐骑会在战斗外打开单位提示时读取一次；更换后的坐骑会在下次悬停时显示。固定角落在 MSUF 编辑模式中放置；光标偏移用于光标锚点。")
T("Adds the current-season Mythic+ score to the main tooltip of another player when Blizzard provides a public score. Unknown or restricted scores stay hidden.", "当暴雪提供公开分数时，将当前赛季的 Mythic+ 分数添加到其他玩家的主要工具提示中。未知或受限的分数保持隐藏。")
T("Adjust the glass effect while keeping your colors and window coverage.", "调整玻璃效果，同时保留你的颜色和窗口覆盖范围。")
T("Adventure Guide", "冒险指南")
T("After a completed Mythic+ run or successful raid encounter, show the public result values in a separate card. Choose which figures appear and how long the card stays open. The last result can be reopened here. Combat delays the card until it is safe to show.", "完成史诗钥石挑战或赢得团队战斗后，在独立卡片中显示公开的结果数值。可选择显示的项目及卡片保留时间，也可在此重新打开上次结果。战斗期间会推迟显示，直到可以安全打开。")
