T("An adjacent button opens a small menu for expansion, Great Vault, Adventure Guide and world map pages. Blizzard's landing button keeps its own click behavior. Menu actions are disabled in combat.", "旁边的按钮可打开资料片概览、宏伟宝库、冒险指南和世界地图的小菜单。暴雪原有的概览按钮仍保持原来的点击功能。战斗中无法使用菜单操作。")
T("An empty allow-list includes every quest. Separate quest IDs with spaces or commas. Daily and weekly exclusions leave a quest manual if its frequency cannot be read. Existing profiles keep their previous behavior until you enable an exclusion.", "允许列表为空时包含所有任务。任务 ID 之间用空格或逗号分隔。如果无法读取任务的重置周期，日常和周常排除会让该任务保持手动。现有配置文件在你启用排除项之前保持原有行为。")
