T("Blizzard keeps the button artwork, clicks, tooltips, enabled states and notifications. Optional glyph artwork is available in the detail controls. Visual changes apply outside combat only.", "按钮图形、点击、鼠标提示、启用状态和通知仍由暴雪保留。可在细节设置中选用符号图形。视觉更改仅在脱离战斗时生效。")
