T("Blizzard original", "暴雪原版")
T("Blizzard owns aggro flashes, progressive highlights and soft target icons. Optional colors tint Blizzard's existing threat textures; its health bar threat color stays under the role-color overlay. Soft target icons also need the nameplate icon switch enabled and a matching soft target in game.", "仇恨闪烁、渐进高亮和软目标图标由暴雪管理。可选颜色用于着色现有威胁材质；血条的威胁颜色仍在职责颜色覆盖层下方。软目标图标还需要启用姓名板图标开关，并在游戏中存在匹配的软目标。")
T("Blizzard owns the aura icons and updates. Choose Keep Blizzard setting or Customize for each unit type. Buffs, debuffs and control effects can be selected and dragged separately in the preview. Aura size uses Blizzard's own setting.", "光环图标及其更新由暴雪负责。为每种单位类型选择“保留暴雪设置”或“自定义”。增益、减益和控制效果可在预览中分别选中和拖动。光环大小使用暴雪自身的设置。")
T("Blizzard owns these elements. The rarity icon setting applies to all nameplates; raid target icons are hidden only on enemy plates. Castbar details control Blizzard's own castbar. The preview and live plates use the same switches.", "这些元素由暴雪负责。稀有度图标设置适用于所有姓名板；团队标记图标仅在敌方姓名板上隐藏。施法条细节控制暴雪自身的施法条。预览和实际姓名板使用相同的开关。")
T("Blizzard personal auras", "暴雪个人光环")
T("Blizzard plate size (health bar + elements)", "暴雪姓名板大小（生命条 + 元素）")
T("Blizzard plate style", "暴雪姓名板样式")
T("Blizzard raid target icon on enemy plates", "敌方姓名板上的暴雪团队标记")
T("Blizzard setting", "暴雪设置")
T("Blizzard shield", "暴雪盾标")
T("Blizzard spell icon", "暴雪法术图标")
T("Blizzard supplies the castbar texture, colors, progress and interrupts. Customize its text and details here. Select and move each cast element in the preview; positions apply outside combat.", "施法条的材质、颜色、进度和打断由暴雪提供。可在此自定义其文字和细节。在预览中选中并移动每个施法元素；位置在脱离战斗后生效。")
T("Blizzard supplies the icons. The Suite keeps its own button plates, bar frame and spacing. Native clicks, tooltips and notifications stay intact.", "图标由暴雪提供。Suite 保留自己的按钮底板、条框架和间距。原生点击、鼠标提示和通知保持不变。")
T("Blizzard supplies the name and health values. Mapko requests full enemy plates and both health values so normal enemies show text too. Width and height change only the enemy health bar in pixels; 0 keeps the selected bar dimensions. Backdrop, border and role fill are separate live skin layers in the preview; right-click a layer for its setting. Role colors use the saved palette; mana is only a caster hint. Open the three-dot menu here or Nameplates in MSUF Colors to change the palette.", "名称和生命值由暴雪提供。Mapko请求完整敌方姓名板及两种生命值，使普通敌人也显示文字。宽度和高度只更改敌方血条的像素尺寸；0保留所选尺寸。预览中的背景、边框和职责填充是独立的实时皮肤层；右键点击某一层可打开对应设置。职责颜色使用已保存的调色板；法力仅作为施法者提示。可在此处的三点菜单或MSUF颜色中的姓名板页面更改调色板。")
