T("Choose %s for \"%s\".", "请选择 %s，设置项为“%s”。")
T("Choose Clean Modern, Midnight Blue, MSUF Forever Glass, Midnight Dark or Class Style for Skinning and enabled Suite modules. Modules enabled later inherit it.", "为皮肤和已启用的 Suite 模块选择简洁现代、Midnight Blue、MSUF Forever 玻璃、Midnight Dark 或职业风格。之后启用的模块会沿用该设置。")
T("Choose Clean Modern, Midnight Blue, Midnight Dark, MSUF Forever or Class Style. This changes only the bag window colors and opacity; item slots and Blizzard bag actions remain intact.", "选择简洁现代、Midnight Blue、Midnight Dark、MSUF Forever或职业风格。仅更改背包窗口的颜色和透明度；物品格位及暴雪背包操作保持不变。")
T("Choose Clean Modern, Midnight Blue, neutral Midnight Dark glass or MSUF Forever's dark gold frame. All use MSUF's bar texture and font. Turn the 20 XP divisions on or off. The lower line can show session gain, XP per hour and time to level. Move or resize the bar in MSUF Edit Mode; its popup edits X, Y, width, height and scale. Hover for exact values. A session survives /reload and starts fresh on the next login.", "可选择 Clean Modern、Midnight Blue、中性的 Midnight Dark 玻璃风格，或 MSUF Forever 的深金色边框。所有风格都使用 MSUF 的状态条材质和字体。可开关经验条的 20 段分隔线。下方一行可显示本次登录获得的经验、每小时经验和预计升级时间。在 MSUF 编辑模式中移动或调整经验条；弹窗可设置 X、Y、宽、高和缩放。鼠标悬停可查看精确数值。会话数据在 /reload 后保留，下次登录重新开始。")
T("Choose Custom layout to set the order of total, per-second and percent values, then pick spaces, brackets or a separator. The percent switch controls main rows; breakdown rows show available shares. Unavailable shares are omitted. Primary means per second for DPS/HPS and total for other meters. Text settings also apply to headers, details and the floating timer. Slug uses WoW's crisp font renderer with an outline and no shadow. Protected values show without a percentage until combat ends.", "选择“自定义布局”可设置总量、每秒和百分比数值的顺序，然后选择空格、括号或分隔符。百分比开关控制主行；明细行显示可用的占比。不可用的占比会被省略。“主要”对 DPS/HPS 指每秒数值，对其他统计指总量。文字设置也适用于标题、详情和浮动计时器。Slug 使用 WoW 清晰的字体渲染器，带描边且无阴影。受保护的数值在战斗结束前不显示百分比。")
T("Choose Suite modules", "选择 Suite 模块")
T("Choose a Suite layout", "选择 Suite 布局")
T("Choose a data source", "选择信息来源")
T("Choose a font", "选择字体")
T("Choose a line, then press Ctrl+C", "选择一行，然后按 Ctrl+C")
T("Choose a look", "选择风格")
T("Choose a look and when the Suite bar appears. Visibility rules use the Suite layout; Blizzard layout keeps Blizzard's visibility. MSUF Edit Mode reveals the bar for moving.", "选择风格以及 Suite 微型菜单的显示时机。可见性规则使用 Suite 布局；暴雪布局保留暴雪的可见性。MSUF 编辑模式会显示该菜单以便移动。")
T("Choose a look below; this sample follows your changes.", "在下方选择风格；此示例会随你的更改而变化。")
T("Choose a look, then adjust its colors.", "选择样式，然后调整颜色。")
T("Choose a preset below or fine-tune with the slider.", "在下方选择预设，或用滑块微调。")
T("Choose a profile that exists in both parts of the suite", "请选择在 Suite 两部分中都存在的配置文件")
T("Choose a random owned Hearthstone variant for the next click", "下次点击随机选择已拥有的炉石变体")
T("Choose a smaller stack size and make sure the item is unlocked, your cursor is empty and you are out of combat.", "请选择较小的堆叠数量，并确保物品未锁定、鼠标未持有物品且已脱离战斗。")
T("Choose a sound", "选择音效")
T("Choose a starting point. Existing bars stay unchanged.", "选择一个起始方案，现有信息条保持不变。")
T("Choose a style above or change these colors to make a Custom look. Rows update immediately.", "选择上面的样式或更改这些颜色以形成自定义外观。行立即更新。")
T("Choose a style, font and coverage in minutes. Every deeper control remains available in Expert mode.", "几分钟即可选好样式、字体和覆盖范围。所有更深入的控制都保留在专家模式中。")
T("Choose a template", "选择模板")
T("Choose an MSUF font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Label, value and warning colors are separate.", "选择 MSUF 字体、描边、阴影以及平滑、锐利或 Slug 渲染。Slug 没有阴影。标签、数值和警告颜色可分别设置。")
T("Choose an MSUF or SharedMedia font and bar texture. Font size, outline, shadow, Smooth/Sharp/Slug rendering, bar height and spacing update the HUD immediately. Slug has no shadow.", "选择 MSUF 或 SharedMedia 字体和条材质。字体大小、描边、阴影、平滑/锐利/Slug 渲染、条高度和间距会立即更新 HUD。Slug 没有阴影。")
T("Choose broad UI families. Dedicated secure behavior and semantic artwork remain untouched.", "选择宽泛的界面类别。专用的安全行为和有含义的图形保持不变。")
T("Choose broker names and discovered currency IDs per place. Select your current-season crest currencies from the native currency list; saved currency selections work after login without visiting an upgrade NPC. Selection order and separator control the crest block. Observed upgrade stages remain available as an alternative after selecting an upgrade item this login. Hearthstone actions require a deliberate click.", "为每个位置选择数据源名称和已发现的货币 ID。从原生货币列表中选择当前赛季的纹章货币；保存的货币选择在登录后即可使用，无需拜访升级 NPC。选择顺序和分隔符控制纹章区块。本次登录期间选择升级物品后，仍可改用已观察到的升级阶段。炉石操作需要主动点击。")
T("Choose buffs and consumables to track.", "选择要追踪的增益和消耗品。")
T("Choose clean window controls and a complete Micro Bar style, then tune individual artwork only when needed.", "选择简洁的窗口按钮和完整的微型菜单样式，仅在需要时再调整单个图形。")
T("Choose coverage", "选择覆盖范围")
T("Choose crest currencies", "选择纹章货币")
T("Choose currencies", "选择货币")
T("Choose data", "选择信息")
T("Choose data for place %d", "为栏位 %d 选择数据")
T("Choose data source", "选择信息来源")
T("Choose discovered currency", "选择已发现的货币")
T("Choose each Blizzard popup separately. The feature hides its window when it appears and leaves the underlying game events intact. Combat lockdown can prevent hiding a protected window.", "可分别选择要隐藏的暴雪弹窗。弹窗出现时只隐藏窗口，游戏事件仍正常触发。战斗限制可能阻止隐藏受保护的窗口。")
T("Choose individual recurring UI errors to hide with Blizzard's own message filter.", "选择个别重复出现的 UI 错误以使用暴雪自己的消息过滤器进行隐藏。")
T("Choose loaded broker", "选择已加载的 Broker 插件")
T("Choose observed seasonal stages", "选择已观察的赛季等级")
T("Choose one font for Blizzard UI text. Existing sizes, outlines, shadows and accessibility scaling are preserved.", "为暴雪界面文字选择一种字体。现有大小、描边、阴影和辅助功能缩放都会保留。")
T("Choose the detailed character view and its extra information. Changing the view reloads the UI.", "选择详细角色视图及其附加信息。更改视图会重载界面。")
T("Choose the dungeon difficulties where MSUF starts the combat log. Mythic+ begins when the keystone starts.", "选择 MSUF 开始战斗记录的地下城难度。史诗钥石在钥石启动时开始记录。")
T("Choose the map shape, then adjust its border and outer shadow.", "选择地图形状，然后调整其边框和外阴影。")
T("Choose the raid difficulties where MSUF starts the combat log.", "选择 MSUF 开始战斗记录的团队副本难度。")
T("Choose the shared button colors and frame. Layout, bindings and visibility stay as set. Changing an individual color switches the label to Custom.", "选择共享的按钮颜色和边框。布局、按键绑定和可见性保持原设置。更改单个颜色会将标签切换为“自定义”。")
T("Choose the values shown on each bar.", "选择每条计量条上显示的数值。")
T("Choose what the Suite tracker lists and when it steps aside.", "选择 Suite 追踪器显示的内容以及何时让位。")
T("Choose where recent actions appear. Delves have their own switch; battlegrounds and arenas share one, and other scenarios follow Outside instances. Where the tracker is switched off, it does not listen to your casts.", "选择最近动作显示的位置。地下堡有单独的开关；战场和竞技场共用一个，其他场景战役跟随“副本外”。在关闭的地方，它不会监听你的施法。")
T("Choose which Blizzard interfaces receive the skin. Blizzard keeps their interactions.", "选择哪些暴雪界面应用皮肤。交互仍由暴雪负责。")
T("Choosing a look updates Skinning and every enabled Suite module. Modules enabled later inherit it. New skin profiles start with %s.", "选择风格会更新皮肤以及所有已启用的 Suite 模块。之后启用的模块会继承它。新的皮肤配置文件以 %s 开始。")
T("Cinematic confirmation can be skipped after you choose to exit. Automatic skipping is a separate option and also skips movies. Both stay inactive during combat, and a vehicle sequence always keeps its exit confirmation. Hide tutorials while this helper is enabled, prefill the DELETE word while keeping the final confirmation manual, hide only the successful screenshot notice, or open your character window at merchants on the tab you used last. At the auction house, Blizzard's filter button is marked while Current Expansion Only is off; tick it there once and Blizzard keeps it for this character.", "选择退出后，可跳过过场动画确认。自动跳过是独立选项，也会跳过影片。两项功能在战斗中均不生效，载具场景始终保留离开确认。此助手还可隐藏教程、预填删除确认词但保留最后的手动确认、仅隐藏截图成功提示，或在商人处以上次使用的标签页打开角色窗口。在拍卖行中，“仅限当前资料片”关闭时会标记暴雪的筛选按钮；在那里勾选一次，暴雪会为此角色保留。")
T("Cinematic zone and event announcements in the Suite look.", "以 Suite 风格显示电影式的区域和事件通告。")
