T("Clean Modern is the Retail default; MSUF Forever is the Forever default. Midnight Blue keeps the original blue glass. Open a section's three-dot menu to change its colors, or use MSUF Colors for the full palette. Your own color changes become Custom.", "简洁现代是正式服默认主题；MSUF Forever是Forever默认主题。Midnight Blue保留原有蓝色玻璃外观。打开某个分区的三点菜单可更改其颜色，或在MSUF颜色中调整完整调色板。自行修改颜色后将变为自定义。")
T("Clean Modern uses matte panels with white accents. Midnight Blue keeps the original blue palette. Midnight Dark uses neutral charcoal glass; MSUF Forever retains its muted gold. Color changes become Custom.", "简洁现代使用带白色点缀的哑光面板。Midnight Blue保留原有蓝色调色板。Midnight Dark使用中性炭灰色玻璃外观；MSUF Forever保留柔和金色。修改颜色后将变为自定义。")
T("Clean Modern, Midnight Blue, Midnight Dark and MSUF Forever are complete looks in Style. Color palettes here change colors only; use Expert mode for every UI state.", "简洁现代、Midnight Blue、Midnight Dark 和 MSUF Forever 是“样式”中的完整风格。这里的调色板只改变颜色；如需调整每种界面状态，请使用专家模式。")
