T("Drag a window by its top edge; drag the bottom-right corner to scale it. The top-right minus button collapses compatible windows to a restore tab. Bags and protected windows keep their native behavior.", "拖动窗口顶边可移动窗口；拖动右下角可缩放。右上角的减号按钮可将兼容的窗口折叠为恢复标签。背包和受保护的窗口保持原生行为。")
T("Drag announcements in MSUF Edit Mode, or set their timing, scale and exact position here.", "在 MSUF 编辑模式中拖动通告，或在此设置其时机、缩放和精确位置。")
