T("Drop an item onto Pinned items in the category sidebar to keep it at the top of every view. Recent items lists up to 200 item types this character received, also across logins; each leaves the list once it is older than the hours set here, and Clear recent items empties it sooner. Neither action moves or deletes an item.", "将物品拖到分类侧栏的“置顶物品”，即可在所有视图中置顶。“最近物品”最多列出本角色获得的200种物品，重新登录后仍会保留；每种物品超过此处设定的小时数后会移出列表，“清空最近物品”可提前清空。这些操作均不会移动或删除物品。")
