T("Enter up to 200 item IDs. A button appears only at a merchant and previews eligible stacks; clicking it opens a confirmation. The helper checks item identity, quality, value, quest status and bag position again before requesting sales. Equippable items require a separate opt-in.", "最多输入 200 个物品 ID。按钮只在商人处出现，并预览符合条件的物品堆；点击后会打开确认窗口。申请出售前，功能会重新检查物品身份、品质、价值、任务状态及背包位置。可装备物品需要单独开启相应选项。")
T("Enter up to eight spell IDs for movement abilities. When movement begins, the first known, ready and usable spell appears briefly; a shared 20-second cooldown limits notices. Empty IDs do no work. MSUF Edit Mode moves the cue.", "最多输入 8 个移动技能的法术 ID。开始移动时，会短暂显示第一个已学会、冷却完毕且可使用的法术。提示共用 20 秒冷却时间，避免频繁出现。ID 留空时不执行任何操作。可在 MSUF 编辑模式中移动提示。")
