T("Equipment choices (the list that opens from a gear slot) show the item level on each item, so you can compare without hovering. The arrows beside the gear slots can be hidden; hold Alt over a slot to open its choices.", "装备选择（从装备栏打开的列表）会显示每件物品的物品等级，无需悬停即可比较。装备栏旁的箭头可以隐藏；在装备栏上按住Alt即可打开选择。")
T("Equipment item levels appear in the upper right of each slot. Choose a font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Missing item data appears when the client provides it.", "装备物品等级显示在每个栏位的右上角。选择字体、描边、阴影以及平滑、锐利或 Slug 渲染。Slug 没有阴影。缺失的物品数据会在客户端提供后显示。")
