T("Every spell of this bar, unlearned ones included. On a buff bar, Add spells offers received buffs such as Power Infusion and Innervate; Buff on me also accepts a buff aura ID or resolvable name and tracks that ID from any caster. With Show missing buffs off, only active buffs appear. The preview edits entries too: click for options, drag to reorder or onto a bar above, middle-click to remove (with undo). Removed spells stay under Add spells. Lists are kept per specialization.", "此条的所有法术，包括未学会的法术。在增益条上，“添加法术”会提供能收到的增益，例如能量灌注和激活；“我身上的增益”也接受增益光环 ID 或可识别的名称，并追踪来自任意施法者的该 ID。关闭“显示缺失的增益”时，只显示生效中的增益。预览也可编辑条目：点击打开选项，拖动以重新排序或拖到上方的条上，中键点击移除（可撤销）。已移除的法术仍列在“添加法术”下。列表按专精分别保存。")
