T("Hide Blizzard's main tooltip in combat, in instances, or for selected item, spell and unit tooltips. MSUF unit and group frame tooltips keep their own visibility settings; aura tooltips keep their Show Tooltip switches. Each choice works independently. A hidden tooltip turns fully transparent, so Blizzard keeps handling it as usual.", "可在战斗中、副本中，或对所选的物品、法术和单位提示隐藏暴雪主鼠标提示。MSUF单位和团队框体的提示仍使用各自的可见性设置；光环提示仍由各自的显示鼠标提示开关控制。各选项独立生效。被隐藏的提示会变为完全透明，暴雪仍照常处理它。")
