T("Hold Alt to see the ID of an item, spell, creature, quest, currency or temporary weapon enchant on its tooltip, or press Alt while the tooltip is open; the IDs stay until the tooltip is built again. Spell icon IDs and Blizzard's account character currency data are optional, and that data joins an open tooltip when it arrives. No ID or quantity appears when the client keeps it private.", "按住Alt可在提示中查看物品、法术、生物、任务、货币或临时武器附魔的ID，也可以在提示打开时按下Alt；ID会保留到提示重新生成为止。法术图标ID和暴雪的其他角色货币数据是可选的，这些数据到达时会加入打开的提示。客户端保持私密的ID或数量不会显示。")
T("Hold Alt to show item, spell, creature, quest, currency and temporary weapon enchant IDs on the main tooltip.", "将鼠标指向物品、法术、生物、任务、货币或临时武器附魔时按住 Alt，可在主鼠标提示中查看 ID。")
