T("Inside a raid the tracker turns into an encounter view at its usual place: boss name, pull timer, the bosses engaged right now with their health, your best wipe and your fastest kill. Phases come from DBM or BigWigs when one is installed; otherwise the phase stays open. A wipe with more bosses down beats one with fewer, and with the same count the one with less boss health left wins. Each character keeps its own records. Boss health shows only while the client reveals it.", "在团队副本中，追踪器会在原位置变成首领战视图：首领名称、开怪计时、当前交战首领及其生命值、你的最佳灭团和最快击杀。安装了 DBM 或 BigWigs 时由其提供阶段，否则阶段留空。击败首领更多的灭团优于更少的；数量相同时，首领剩余生命值更少者胜出。每个角色各自保存记录。首领生命值仅在客户端公开时显示。")
