T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "保留暴雪网格，或选择 Suite 单一网格、按实际背包分组或分类。在背包窗口中使用“编辑分类”创建、重命名、排序或禁用分类；将物品拖到侧栏分类即可分配。大型背包可滚动查看或使用上一页、下一页；战斗中会同时显示所有格子。堆叠合并仅影响显示；在银行、公会银行、邮件、交易、拍卖行和商人处始终恢复显示实际堆叠。")
