T("Limit the whole highlight to combat, to instances or to the open world, then give the pointer ring, the global cooldown and the cast fill their own combat rule. Nothing follows the pointer while it is hidden.", "将整个高亮限制在战斗中、副本内或野外，然后为指针圆环、公共冷却和施法填充分别设置战斗规则。隐藏时不会有任何东西跟随指针。")
