T("Mainline covers Rogue poisons, this season's flasks, augment runes and weapon oils, and the Well Fed food buff. Each category clicks the first matching item in your bags; an item you enter for it is tried first. Food is found in your bags by the game's eating spells: the food you enter comes first, then the newest one. With the gray reminder on, a category with nothing left stays visible without a click action. Assassination prefers Deadly Poison; Outlaw and Subtlety prefer Instant Poison. Dragon-Tempered Blades allows two poisons per category. Oils target equipped weapons; known Shaman or Paladin imbues suppress automatic oils.", "Mainline 涵盖潜行者毒药、本赛季的合剂、强化符文和武器油，以及“进食充分”食物增益。每个类别点击时使用背包中第一个符合的物品；为其填写的物品会优先尝试。食物会按照游戏的进食法术在背包中查找：先使用你填写的食物，然后是最新的食物。开启灰色提醒后，用完的类别仍会显示，但没有点击动作。奇袭优先致命药膏，狂徒和敏锐优先速效药膏。龙淬之刃允许每个类别两种毒药。武器油作用于已装备的武器；已学会萨满或圣骑士的武器附魔时不会自动提醒武器油。")
