T("Mapko uses Modern plates, Medium size and the same bar dimensions on Retail and Forever. Guild names and titles also affect names in the world. Bind Toggle friendly NPC nameplates under MSUF Suite in Blizzard Key Bindings. Import protection keeps your current nameplates when importing a full Suite profile; explicit nameplate imports still replace them.", "Mapko在正式服和Forever上使用现代姓名板、中等尺寸和相同条形尺寸。公会名称和头衔也会影响世界中的名称。可在暴雪按键设置的MSUF Suite下绑定“切换友方NPC姓名板”。导入保护会在导入完整Suite配置时保留当前姓名板；单独导入姓名板仍会替换其设置。")
