T("Priority: focus, safe tank aggro, threat, tapped, quest, neutral, then NPC type. Turning focus off allows the next rule. Disabled threat overrides preserve Blizzard's active threat color. Tank mode uses your effective role; warnings also work for damage/healers. Secret values stay with Blizzard.", "优先级：焦点、坦克稳定仇恨、威胁、已被他人攻击、任务、中立，然后是 NPC 类型。关闭焦点后会应用下一条规则。禁用的威胁覆盖会保留暴雪当前的威胁颜色。坦克模式使用你的实际职责；警告也适用于伤害输出和治疗者。保密数值仍由暴雪处理。")
