T("Repair equipment and sell poor-quality items when a merchant opens. Hold Shift to skip selling.", "打开商人时修理装备并出售粗糙品质物品。按住 Shift 可跳过出售。")
T("Repairs only when the cost is within your limit. Guild funds are used first when allowed.", "仅在费用不超过你的上限时修理。允许时优先使用公会资金。")
