T("Replace objectives with the Mythic+ timer during a key", "史诗钥石期间用计时器替换目标")
T("Replaces the merchant's pages with one list; scroll it with the mouse wheel or the bar. Right-click buys, left-click picks an item up and Shift-click asks for a quantity; linking and previewing work as usual. Purchases paid with currencies or items, or costing at least 150 gold, ask for confirmation first. The buyback tab keeps Blizzard's layout. Drop or click an item from your bags onto the list to sell it; one you can still refund asks whether to refund it.", "用一个列表取代商人的分页；可用鼠标滚轮或滚动条滚动。右键购买，左键拿起物品，Shift+点击询问数量；链接和预览照常可用。使用货币或物品支付，或价格至少150金币的购买会先请求确认。回购标签页保持暴雪的布局。将背包中的物品拖放或点击到列表上即可出售；仍可退款的物品会询问是否退款。")
T("Report junk sale requests in chat", "在聊天中报告出售垃圾物品的请求")
T("Reports group member deaths in chat during combat.", "战斗中队伍成员死亡时，在聊天窗口报告。")
T("Reports the first observed death of each group member during combat. Local chat, a screen notice and a sound can be selected separately. Simultaneous deaths share one sound. Optionally include your own death. The listener is active only while you are grouped and in combat.", "通报战斗中首次观察到的各队员死亡。可分别选择本地聊天、屏幕提示和声音。同时发生的死亡仅播放一次声音，也可包含自己的死亡。仅在组队且处于战斗时监听。")
