T("Show weather as text, an icon, or both. Choose Blizzard icons or original Forever artwork. The tooltip keeps the weather name when only the icon is shown.", "以文字、图标或两者显示天气。可选择暴雪图标或 Forever 原创图案。仅显示图标时，鼠标提示仍会显示天气名称。")
T("Show weekly reward item levels", "显示每周奖励物品等级")
T("Show who each cast targets", "显示每个施法的目标")
T("Show windows", "显示窗口")
T("Show your Bloodlust exhaustion or ready state while grouped.", "组队时显示自己受到嗜血类效果后的疲劳状态，或显示可用状态。")
T("Show your owned item count, including bank and Warband bank, on item tooltips.", "在物品工具提示上显示您拥有的物品数量，包括银行和战团银行。")
T("Show your selected loot specialization in the Great Vault window.", "在宏伟宝库窗口中显示你所选的拾取专精。")
T("Show zone", "显示区域")
T("Shown value", "显示的数值")
T("Shown windows: %d. Raise the number of windows to show this one.", "已显示窗口：%d。增加窗口数量即可显示此窗口。")
T("Shows Blizzard's shared battle resurrection charges in an active Mythic+ run or raid encounter. The icon counts down to the next charge using Blizzard's cooldown display. Hidden when the shared pool is unavailable. MSUF Edit Mode previews the display and edits X, Y, width, height and scale.", "在进行中的史诗钥石或团队首领战中显示暴雪的共享战斗复活次数。图标使用暴雪的冷却显示倒计时到下次充能。共享次数不可用时隐藏。MSUF 编辑模式可预览显示并编辑 X、Y、宽度、高度和缩放。")
T("Shows an approximate range to your current target from the game's range checks of spells you know; values include the target's hitbox, and dashes mean that no known spell can tell. Write the text with {range} and {unit}. The estimate can sit below the target frame, following it when the frame moves, or anywhere on screen; MSUF Edit Mode moves both placements.", "根据你已知法术的游戏射程判定，显示与当前目标的大致距离；数值包含目标的受击范围，显示短横表示没有已知法术能够判断。用 {range} 和 {unit} 编写文字。估算值可以放在目标框体下方（框体移动时随之移动），也可以放在屏幕任意位置；MSUF 编辑模式可移动这两种位置。")
T("Shows incoming damage and healing for you or your vehicle. Blizzard's own combat text is hidden while enabled and restored when disabled. Move the display in MSUF Edit Mode. During heavy bursts the oldest of the visible messages is replaced. The game may keep amounts private, so messages are never combined or filtered by their value.", "显示你或载具受到的伤害和治疗。启用时隐藏暴雪自身战斗文字，关闭后恢复。可在 MSUF 编辑模式中移动显示位置。消息密集时替换最早的可见消息。游戏可能隐藏数值，因此不会合并消息或按数值过滤。")
T("Shows item levels on merchant equipment when Blizzard has loaded its item data. Buyback items and items without an item level stay unchanged.", "暴雪载入物品数据后，在商人出售的装备上显示物品等级。回购物品和没有物品等级的物品保持不变。")
T("Shows the current loot specialization when you open the Great Vault. Updates if you change loot specialization while the window is open.", "打开宏伟宝库时显示当前的拾取专精。窗口打开期间更改拾取专精时会随之更新。")
T("Shows the lowest equipped durability below your chosen threshold, outside combat. MSUF Edit Mode shows a sample even when your gear is repaired. Its popup edits X, Y, width, height and scale.", "脱离战斗时，若已装备物品的最低耐久度低于所选阈值则显示。即使装备已修理，MSUF 编辑模式也会显示示例。其弹出窗口可编辑 X、Y、宽度、高度和缩放。")
T("Shows the number you own, including your bank and Warband bank, when the item tooltip has a public item ID. Optionally separate storage locations. Empty counts are omitted.", "当物品鼠标提示提供公开物品 ID 时，显示你拥有的数量，包括银行和战团银行。可选择按存储位置分别显示；数量为零的项目会省略。")
T("Shows the total durability of your gear on the character model, moved by the two offsets, and crops the edges of the gear slot icons on your character sheet and in the Inspect window.", "在角色模型上显示装备的总耐久度，并按两个偏移移动，同时裁剪角色面板和观察窗口中装备栏图标的边缘。")
T("Shows up to three extra compact notices for Blizzard personal item-loot toasts. Filter by minimum quality, mount or pet items, and optionally up to 100 item IDs. Native Blizzard notices remain visible; ordinary bag additions without a toast are not included.", "暴雪显示个人物品拾取提示时，额外显示最多三条简洁提示。可按最低品质、坐骑或宠物物品，以及最多 100 个物品 ID 筛选。暴雪原有提示仍会显示；没有拾取提示的普通背包物品不包括在内。")
T("Shows your current talent build and loot specialization on ready checks, when a dungeon queue pops, or when you enter an instance. It never changes your talents or loot spec.", "就位确认、地下城排队匹配成功或进入副本时，显示当前天赋配置和拾取专精。不会自动更改天赋或拾取专精。")
T("Shows your most recent successful spells. Standard rows have an icon, name and marker; Icons only is a compact vertical icon column. Display width applies to standard rows; icon width follows row height in the icon preset. Position and anchor are set in MSUF Edit Mode, which shows sample actions. The list stops listening while disabled. Spells whose details the client keeps private cannot appear.", "显示最近成功施放的法术。标准行包含图标、名称和标记；“仅图标”预设则是紧凑的竖排图标。显示宽度只影响标准行；图标预设的宽度由行高决定。可在 MSUF 编辑模式中设置位置和锚点，并查看示例动作。关闭后不再监听法术事件。客户端未公开详情的法术无法显示。")
T("Shows your own Bloodlust exhaustion while in a group, or a ready state if you prefer. Relevant player aura changes update it; MSUF Edit Mode moves it and previews the locked state.", "组队时显示你自身的嗜血疲劳状态，也可选择显示可用状态。相关玩家光环变化时会更新；可在 MSUF 编辑模式中移动并预览疲劳状态。")
