T("Start with a look, then tune its artwork, glow and plate. Changing a detail switches the preset label to Custom without losing the other settings.", "先选择一个风格，然后调整其装饰图、发光和底板。更改细节会将预设标签切换为“自定义”，且不会丢失其他设置。")
