T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "使用银行窗口下方的按钮切换原生标签页、合并银行、合并战团银行和共享分类。共享分类包含可访问的角色及战团银行标签页。“管理银行标签页”会返回暴雪的购买、存款和标签页设置界面。每个格位保留自己的物品操作，银行堆叠不会合并；点击战团物品时会先选中暴雪的“战团银行”标签页，可退款物品在进入战团银行前会先询问。")
T("Switch each bar on or off here. Turning it back on restores its previous visibility mode. Select Layout to customize the bar selected above.", "在此分别开启或关闭动作条。重新开启时会恢复之前的显示模式。选择布局即可调整上方选中的动作条。")
T("Switch the whole Skinning module here, or adjust Blizzard and Suite windows separately below.", "在此开关整个皮肤模块，或在下方分别调整暴雪和 Suite 窗口。")
