T("Ten action bars plus stance and pet bars with free layout, paging, visibility rules and button styling. Key bindings keep using Blizzard's commands.", "十个动作条外加姿态条和宠物动作条，支持自由布局、翻页、可见性规则和按钮样式。按键绑定仍使用暴雪的命令。")
