T("Tick every demon you want out; demons your character has not learned yet can be ticked too. A summoned demon you left unticked gets a notice, as long as one of your ticked demons can be summoned. Another look of a demon counts as that demon once you have summoned it in that look.", "勾选你想召唤出来的每个恶魔；角色尚未学会的恶魔也可以勾选。召唤出未勾选的恶魔时会显示提示，前提是你勾选的恶魔中有一个可以召唤。恶魔的其他外观在你以该外观召唤过一次后，会算作同一个恶魔。")
