T("Timestamps use Blizzard's chat setting across all chat windows. Copy is off by default; when enabled, move its button with X/Y, choose a message, then press Ctrl+C. The displayed timestamp is included when timestamps are on. The message tools leave the Combat Log alone (its own settings can add a timestamp to every line); its lines still wake the idle fade. Saved history belongs to this character.", "时间戳在所有聊天窗口中使用暴雪的聊天设置。复制功能默认关闭；启用后，可用 X/Y 移动其按钮，选择一条消息，然后按 Ctrl+C。开启时间戳时，复制内容会包括显示的时间戳。消息工具不会处理战斗记录（它自己的设置可以为每一行加上时间戳）；战斗记录的新行仍会唤醒闲置淡出。保存的历史记录属于当前角色。")
